from typing import List


def threePartitionArray(arr: List[int], lowVal: int, highVal: int) -> List[int]:
    small, low_hits, mid, high_hits, big = [], [], [], [], []
    for x in arr:
        if x < lowVal:
            small.append(x)
        elif x > highVal:
            big.append(x)
        elif x == lowVal:
            low_hits.append(x)
        elif x == highVal:
            high_hits.append(x)
        else:
            mid.append(x)
    # 中间段把 lowVal 放最前、highVal 放最后，保证 lowVal 在 highVal 之前
    return small + low_hits + mid + high_hits + big


def _check(arr, lo, hi):
    res = threePartitionArray(arr, lo, hi)
    assert sorted(res) == sorted(arr)
    g = [0 if x < lo else 2 if x > hi else 1 for x in res]
    assert g == sorted(g)
    if lo in res and hi in res:
        assert max(i for i, x in enumerate(res) if x == lo) < min(i for i, x in enumerate(res) if x == hi) or lo == hi
    return res


if __name__ == "__main__":
    print(_check([1, 14, 5, 20, 4, 2, 54, 20, 87, 98, 3, 1, 32], 14, 20))
    print(_check([7, 3, 9, 3, 7, 1], 3, 7))
    print("ok")
